    let (changed, got) = bcf_run(bcf_s("scale=2; 3.5 + 0.0"));
    assert!(changed, "the strip must fire");
    assert_eq!(got.as_deref(), Some("scale=2; 3.5"), "stripped text");
    let (changed, got) = bcf_run(bcf_s("3.5 + 0.0  "));
