    let (changed, got) = bcf_run(bcf_s("3.5 +  0.0"));
    assert!(changed, "the strip must fire");
    assert_eq!(got.as_deref(), Some("3.5"), "stripped text");
    let (changed, got) = bcf_run(bcf_interp("3.5 + ", "$v", " + 0.0"));
    assert!(changed, "the Interpolate last part must be stripped");
    assert_eq!(got.as_deref(), Some("3.5 + ${x}"), "stripped interpolate");
