    assert!(!changed, "the strip must refuse this shape");
    assert_eq!(got.as_deref(), Some("3.5 + -0.0"), "argument untouched");
    let (changed, got) = bcf_run(bcf_s("3.5"));
    assert!(!changed, "the strip must refuse this shape");
    assert_eq!(got.as_deref(), Some("3.5"), "argument untouched");
    let (changed, got) = bcf_run(bcf_s("0.0"));
    assert!(!changed, "the strip must refuse this shape");
    assert_eq!(got.as_deref(), Some("0.0"), "argument untouched");
    let (changed, got) = bcf_run(bcf_s(""));
    assert!(!changed, "the strip must refuse this shape");
